DROP TABLE IF EXISTS `cce_marks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `cce_marks` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `academic_year` varchar(10) NOT NULL,
  `semester` tinyint(4) NOT NULL DEFAULT 1,
  `fe1` decimal(5,1) DEFAULT NULL,
  `fe2` decimal(5,1) DEFAULT NULL,
  `fe3` decimal(5,1) DEFAULT NULL,
  `fe4` decimal(5,1) DEFAULT NULL,
  `fe5` decimal(5,1) DEFAULT NULL,
  `fe6` decimal(5,1) DEFAULT NULL,
  `fe7` decimal(5,1) DEFAULT NULL,
  `fe8` decimal(5,1) DEFAULT NULL,
  `se1` decimal(5,1) DEFAULT NULL,
  `se2` decimal(5,1) DEFAULT NULL,
  `se3` decimal(5,1) DEFAULT NULL,
  `fe_total` decimal(6,1) DEFAULT 0.0,
  `se_total` decimal(6,1) DEFAULT 0.0,
  `grand_total` decimal(6,1) DEFAULT 0.0,
  `percent` decimal(5,2) DEFAULT 0.00,
  `grade` varchar(10) DEFAULT NULL,
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_mark` (`student_id`,`subject_id`,`academic_year`,`semester`),
  KEY `idx_school` (`school_id`,`academic_year`,`semester`),
  KEY `subject_id` (`subject_id`)
) ENGINE=InnoDB AUTO_INCREMENT=644 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
