CREATE TABLE `cce_note_dropdown` (
  `noteid` int(11) NOT NULL,
  `std` int(11) DEFAULT NULL,
  `semister` int(11) DEFAULT NULL,
  `s1` varchar(182) DEFAULT NULL,
  `s2` varchar(132) DEFAULT NULL,
  `s3` varchar(136) DEFAULT NULL,
  `s4` varchar(172) DEFAULT NULL,
  `s5` varchar(166) DEFAULT NULL,
  `s6` varchar(124) DEFAULT NULL,
  `s7` varchar(138) DEFAULT NULL,
  `s8` varchar(154) DEFAULT NULL,
  `s9` varchar(196) DEFAULT NULL,
  `s10` varchar(124) DEFAULT NULL,
  `s11` varchar(78) DEFAULT NULL,
  `s12` varchar(80) DEFAULT NULL,
  `s13` varchar(128) DEFAULT NULL,
  PRIMARY KEY (`noteid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
