  `parvat3` varchar(188) DEFAULT NULL,
  `akash1` varchar(324) DEFAULT NULL,
  `akash2` varchar(224) DEFAULT NULL,
  `akash3` varchar(230) DEFAULT NULL,
  `std` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
