CREATE TABLE `cce_student_outcomes` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `school_id` int(11) NOT NULL,
  `student_id` int(11) NOT NULL,
  `academic_year` varchar(10) NOT NULL,
  `semester` tinyint(4) NOT NULL DEFAULT 1,
  `outcome_id` int(11) NOT NULL,
  `outcome_text` text DEFAULT NULL,
  `achieved` tinyint(1) DEFAULT 1,
  `level` tinyint(4) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_out` (`student_id`,`academic_year`,`semester`,`outcome_id`),
  KEY `school_id` (`school_id`)
) ENGINE=InnoDB AUTO_INCREMENT=486 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
